    INSERT INTO data_product (id, archived, created_by, created_at, modified_by, modified_at, name, description, rest_client_identifier_code, rest_client_method_code, rest_client_path_template, rest_client_request_template, flow_code, data_source_system_id, deprecated_since, rest_client_change_detection_path_template, rest_client_id, state_code, data_provider_uid, payment_required, pricing_basis, extended_description, links)
    VALUES
    -- Acontrol
    ('c009a1f9-7c16-4a47-b79a-9c9224ac55d2', false, null, NOW(), null, NOW(), '{"de": "11 Graslandbasierte Milch- und Fleischproduktion", "fr": "11 Production de lait et de viande basée sur les herbages", "it": "11 Produzione di latte e carne basata sulla superficie inerbita"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Angaben zu Kontrollen aus dem Kontrollbereich 11 Graslandbasierte Milch- und Fleischproduktion mit den Ergebnissen pro Kontrollpunkt.", "fr": "Ce produit de données contient des indications sur les contrôles du domaine de contrôle 11 Production de lait et de viande basée sur les herbages avec les résultats par point de contrôle.", "it": "Questo prodotto di dati contiene i controlli relativi all’ambito di controllo 11 Produzione di latte e carne basata sulla superficie inerbita con i risultati per ciascun punto di controllo."}'::jsonb, 'ACONTROL_API', 'POST', 'inspection/1', '{"unitIdentifiers":[{"unitIdentifier":"{{bur}}","type":"BurId"}],"inspectionDomainIds":["11"],"pageOffset":{{pageOffset}},"pageSize":{{pageSize}}}', 'BUR_BASED_PRE_VALIDATION', '810af188-8800-48f8-9b12-0276bb4b4e0e', null, null, '5d3a4a87-63fc-4428-8044-313d222efe1d', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Die Datenprodukte enthalten Angaben zu Kontrollen auf dem Betrieb aus dem aktuellen Jahr und den letzten drei Kalenderjahren. Je nach Abfragezeitpunkt und Kontrollstatus sind somit Kontrollen von maximal 4 Jahren enthalten.</p><p>Wenn der Betrieb an eine neue Bewirtschafterin oder einen neuen Bewirtschafter übergeben wurde, so werden nur Kontrollen ab dem Datum des Bewirtschafterwechsels angegeben.</p><p>Alle Datenprodukte enthalten unabhängig von den fachlichen Inhalten dieselben Attribute. Die «tiefste» Ebene der Kontrollangaben ist der «Kontrollpunkt» mit der Beschreibung des Kontrollresultats und des Mangels, falls ein solcher vorliegt. Massnahmen werden nicht erwähnt.</p><p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>BUR</p></li><li><p>KT_ID_B</p></li><li><p>UID</p></li><li><p>KT_ID_P</p></li><li><p>TVD ID</p></li><li><p>Kontrollart</p></li><li><p>Kontrollstelle</p></li><li><p>Kontrolldatum</p></li><li><p>ID Rubrik</p></li><li><p>Rubrik Kurzname</p></li><li><p>Ergebnis Rubrik</p></li><li><p>Kontrollgrund</p></li><li><p>ID Punktegruppe</p></li><li><p>Punktgruppe Kurzname</p></li><li><p>ID Kontrollpunkt</p></li><li><p>Kontrollpunkt Kurzname</p></li><li><p>Kontrollergebnis</p></li><li><p>Mangelbeschreibung</p></li></ul><p></p>", "fr": "<p>Les produits de données comprennent les contrôles de l’année en cours et des trois années précédentes complètes. Selon le moment de la consultation et le statut du contrôle, ils englobent donc les contrôles de 4 années au maximum.</p><p>Si l’exploitation a été transmise à un nouvel exploitant, seuls les contrôles effectués à partir de la date du changement d’exploitant sont indiqués.</p><p>Tous les produits de données d’Acontrol contiennent les mêmes attributs, indépendamment de leur contenu technique. Le niveau « le plus bas » des données de contrôle est le « point de contrôle » avec la description du résultat du contrôle et, le cas échéant, du manquement. Les mesures ne sont pas mentionnées.</p><p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>No REE</p></li><li><p>KT_ID_B</p></li><li><p>IDE</p></li><li><p>KT_ID_P</p></li><li><p>ID BDTA</p></li><li><p>Type de contrôle</p></li><li><p>Organisation de contrôle</p></li><li><p>Date de contrôle</p></li><li><p>ID Rubrique</p></li><li><p>Rubrique abréviation</p></li><li><p>Résultat rubrique</p></li><li><p>Motif de contrôle</p></li><li><p>ID Groupe de points</p></li><li><p>Groupe de points abréviation</p></li><li><p>ID Point de contrôle</p></li><li><p>Point de contrôle abréviation</p></li><li><p>Résultat du contrôle</p></li><li><p>Description du manquement</p></li></ul><p></p>", "it": "<p>I prodotti di dati contengono i controlli dell’anno in corso e dei tre anni civili precedenti. A seconda della data della consultazione e dello stato del controllo sono quindi contenuti i controlli relativi a un massimo di 4 anni.</p><p>Se l’azienda è stata ceduta a un nuovo gestore vengono indicati solo i controlli a partire dalla data del cambio di gestore.</p><p>Tutti i prodotti di dati contengono gli stessi attributi indipendentemente dai contenuti tecnici. Il livello «più basso» dei dati dei controlli è il «punto di controllo» con la descrizione del risultato del controllo e, se del caso, della lacuna. Le misure non sono menzionate.</p><p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>N RIS</p></li><li><p>KT_ID_B</p></li><li><p>IDI</p></li><li><p>KT_ID_P</p></li><li><p>ID BDTA</p></li><li><p>Tipo di controllo</p></li><li><p>Ente di controllo</p></li><li><p>Data di controllo</p></li><li><p>ID Rubrica</p></li><li><p>Rubrica abbreviazione</p></li><li><p>Risultato rubrica</p></li><li><p>Motivo del controllo</p></li><li><p>ID Gruppo di punti</p></li><li><p>Gruppo di punti abbreviazione</p></li><li><p>ID Punto di controllo</p></li><li><p>Punto di controllo abbreviazione</p></li><li><p>Risultato del controllo</p></li><li><p>Descrizione della lacuna</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('9f3a2e49-7196-41b7-a3da-0a83b3f5e386', false, null, NOW(), null, NOW(), '{"de": "12 Tierwohl", "fr": "12 Bien-être des animaux", "it": "12 Benessere degli animali"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Angaben zu Kontrollen aus dem Kontrollbereich 12 Tierwohl mit den Ergebnissen pro Kontrollpunkt.", "fr": "Ce produit de données contient des indications sur les contrôles du domaine de contrôle 12 Bien-être des animaux avec les résultats par point de contrôle.", "it": "Questo prodotto di dati contiene i controlli relativi all’ambito di controllo 12 Benessere degli animali con i risultati per ciascun punto di controllo."}'::jsonb, 'ACONTROL_API', 'POST', 'inspection/1', '{"unitIdentifiers":[{"unitIdentifier":"{{bur}}","type":"BurId"}],"inspectionDomainIds":["12"],"pageOffset":{{pageOffset}},"pageSize":{{pageSize}}}', 'BUR_BASED_PRE_VALIDATION', '810af188-8800-48f8-9b12-0276bb4b4e0e', null, null, '5d3a4a87-63fc-4428-8044-313d222efe1d', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Die Datenprodukte enthalten Angaben zu Kontrollen auf dem Betrieb aus dem aktuellen Jahr und den letzten drei Kalenderjahren. Je nach Abfragezeitpunkt und Kontrollstatus sind somit Kontrollen von maximal 4 Jahren enthalten.</p><p>Wenn der Betrieb an eine neue Bewirtschafterin oder einen neuen Bewirtschafter übergeben wurde, so werden nur Kontrollen ab dem Datum des Bewirtschafterwechsels angegeben.</p><p>Alle Datenprodukte enthalten unabhängig von den fachlichen Inhalten dieselben Attribute. Die «tiefste» Ebene der Kontrollangaben ist der «Kontrollpunkt» mit der Beschreibung des Kontrollresultats und des Mangels, falls ein solcher vorliegt. Massnahmen werden nicht erwähnt.</p><p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>BUR</p></li><li><p>KT_ID_B</p></li><li><p>UID</p></li><li><p>KT_ID_P</p></li><li><p>TVD ID</p></li><li><p>Kontrollart</p></li><li><p>Kontrollstelle</p></li><li><p>Kontrolldatum</p></li><li><p>ID Rubrik</p></li><li><p>Rubrik Kurzname</p></li><l