    -- AGIS
    ('46f8a883-da7c-49b3-b986-10a24b1e09ef', false, null, NOW(), null, NOW(), '{"de": "Anmeldungsdaten für die Direktzahlungsarten, den ÖLN und die Kontrollstellen", "fr": "Données d’inscription pour les types de paiements directs, les PER et les organes de contrôle", "it": "Dati di notifica per i tipi di pagamenti diretti, la PER e gli organi di controllo"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Anmeldedaten für die Direktzahlungsprogramme, für den Ökologischen Leistungsnachweis (ÖLN) sowie die Kontrollstelle. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient les données d’inscription pour les programmes des paiements directs, les prestations écologiques requises (PER) et les organes de contrôle. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene i dati di notifica per i programmi dei pagamenti diretti, per la prova che le esigenze ecologiche sono rispettate (PER) e per gli organi di controllo. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'eco-etho-data/1/ecoetho', '{"registrationYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'eco-etho-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=controlOrganizationName&type=programName', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in wie Datenprodukt “Betrieb”</p></li><li><p>Kontrollstellen, welche für den Betrieb zuständig sind</p></li><li><p>Namen der Direktzahlungsart, für die die Anmeldung erfolgt.</p></li><li><p>Für dieses Jahr gültige Anmeldun</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Organe de contrôle pour les PER.</p></li><li><p>Nom de l’inscription</p></li><li><p>Année d’inscription</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>Organo di controllo competente per l’azienda</p></li><li><p>Nome del tipo di pagamenti diretti per i quali è effettuata la notifica</p></li><li><p>Notifica valida per quest’anno</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('a795d0b0-f177-4bb4-8e41-1ed12d358c79', false, null, NOW(), null, NOW(), '{"de": "Nutztiere in Sömmerung", "fr": "Animaux de rente en estivage", "it": "Animali da reddito estivati"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Art und Anzahl Nutztiere pro Betrieb, die im Inland gesömmert wurden. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient l’espèce et le nombre d’animaux de rente qui ont été estivés dans le pays. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti gli animali da reddito (specie e numero) per azienda estivati all’interno del Paese. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["animalSummeringData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=animalSummeringData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer des Tierstandorts</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in wie Datenprodukt “Betrieb”</p></li><li><p>Tierkategorie</p></li><li><p>Daten aus der TVD</p><ul><li><p>Anzahl gesömmerte Tiere</p></li><li><p>GVE der gesömmerten Tiere</p></li><li><p>Normalstösse der gesömmerten Tiere</p></li><li><p>Durchschnittliche Anzahl Aufenthaltstage auf dem Sömmerungsbetrieb</p></li></ul></li><li><p>Daten aus der Selbstdeklaration</p><ul><li><p>Anzahl gesömmerte Tiere</p></li><li><p>Sömmerungsdauer in Anzahl Tagen</p></li></ul></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE du lieu où sont gardés les animaux</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Catégorie d’animaux</p></li><li><p>Données BDTA</p><ul><li><p>Nombre d’animaux estivés</p></li><li><p>Nombre d’UGB estivés</p></li><li><p>Nombre de PN estivés</p></li><li><p>Durée moyenne du séjour sur l’exploitation d’estivage</p></li><li><p>Nombre d’animaux qui n’ont pas encore été sortis de l’exploitation d’estivage au moment de l’extraction des données d’estivage</p></li></ul></li><li><p>Données du recensement</p><ul><li><p>Nombre d’animaux estivés pour la catégorie et la durée d’estivage</p></li><li><p>Durée de l’estivage en jours</p></li></ul></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS dell’ubicazione degli animali</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>Categoria animale</p></li><li><p>Dati della BDTA</p><ul><li><p>Numero di animali estivati</p></li><li><p>UBG di animali estivati</p></li><li><p>Carichi normali di animali estivati</p></li><li><p>Numero medio di giorni di permanenza nell’azienda d’estivazione</p></li><li><p>Numero di animali che al momento dell’estrapolazione dei dati relativi all''estivazione non sono ancora stati cancellati dall''azienda d’estivazione</p></li></ul></li><li><p>Dati dell’autodichiarazione</p><ul><li><p>Numero di animali estivati</p></li><li><p>Durata d’estivazione in giorni</p></li></ul></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('147e8c40-78cc-4db3-a909-65504aa62a64', false, null, NOW(), null, NOW(), '{"de": "Betrieb", "fr": "Exploitation", "it": "Azienda"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Angaben zu Betrieben (von Tierhaltern und Bewirtschaftern), wie: kantonale Betriebsnummer, BUR Nummer, TVD-Nummer, Standortadresse, Koordinaten, Betriebsform, Personenbeziehung des Betriebs, Betriebseigenschaften", "fr": "Ce produit contient des informations générales sur les exploitations des éleveurs et des exploitants, telles que : numéro d’identification cantonal de la forme d’exploitation, numéro REE, numéro BDTA, adresse du site, coordonnées, forme d’exploitation, relation de personnes de l’exploitation, caractérstiques de l’exploitation", "it": "Questo prodotto contiene informazioni concernenti le aziende (detentori di animali e gestori): numero aziendale cantonale, numero RIS, numero BDTA, ubicazione, coordinate, forma di azienda, rapporto tra la persona e l’azienda, farmCharacteristics"}'::jsonb, 'AGIS_API', 'POST', 'register-data/1/register', '{"farmSearchParameters":{"uid":"{{uid}}"},"dataRequestType":{"relationDepth":"personToFarmRelations"}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', '2026-03-06 00:00:00.000', 'register-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=farm&type=farmToFarmRelations&type=personToFarmRelations', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, null, null),
    ('64e39df0-2e56-4204-9c44-a43e1e26a2e8', false, null, NOW(), null, NOW(), '{"de": "Biodiversitätsförderflächen", "fr": "Surfaces de promotion de la biodiversité", "it": "Superfici per la promozione della biodiversità"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Biodiversitätsförderflächen gemäss Direktzahlungsverordnung (DZV). Die Angaben sind aufgegliedert nach der Zone, Hauptkultur und Betrieb. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient les données sur les surfaces de promotion de la biodiversité selon l’ordonnance sur les paiements directs (OPD). Les données sont séparées selon la zone, la culture principale et l’exploitation. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti le superfici per la promozione della biodiversità secondo l’ordinanza sui pagamenti diretti (OPD). I dati sono suddivisi per zona, coltura principale e azienda. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["biodiversitySurfaceData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=biodiversitySurfaceData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>ID der Fläche</p></li><li><p>Eindeutige kantonale ID der Fläche / Kultur</p></li><li><p>Lokalisierung des Standortes</p></li><li><p>Identifikationsnummer der Standortgemeinde</p></li><li><p>Landwirtschaftliche Zone</p></li><li><p>Code der Kulturart</p></li><li><p>Zusätzliche Ausprägung der Kulturart</p></li><li><p>Bruttofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Nettofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Biodiversität-Qualitätsstufe</p></li><li><p>Jahr, in welchem die Verpflichtung zur BFF begonnen hat.</p></li><li><p>Fläche mit einem Vertrag gemäss Natur- und Heimatschutzgesetz (NHG)</p></li><li><p>Jahr, in welchem die Verpflichtung aus dem NHG-Vertrag begonnen hat.</p></li><li><p>Fläche im Beitragsjahr genutzt</p></li><li><p>Fläche beitragsberechtigt</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Identifiant de la surface</p></li><li><p>Identifiant cantonal unique de la surface / culture</p></li><li><p>Localisation de l’emplacement</p></li><li><p>Numéro d’identification de la commune d’emplacement</p></li><li><p>Zone agricole</p></li><li><p>Code du genre de culture</p></li><li><p>Surface brute en m2 ou pour les arbres, leur nombre</p></li><li><p>Surface nette en m2 ou pour les arbres, leur nombre</p></li><li><p>Niveau de qualité de la biodiversité</p></li><li><p>Année durant laquelle l’engagement pour la SPB a commencé</p></li><li><p>Transmettre un flag avec 1 dans le cas des surfaces SPB pour lesquelles il existe un contrat LPN ou une base légale cantonale</p></li><li><p>Année pendant laquelle l’engagement pour le contrat LPN a commencé</p></li><li><p>Ce flag indique qu’une surface SPB a été utilisée / exploitée ou non l’année en question</p></li><li><p>Ce flag concerne le droit aux contributions des surfaces SPB</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>ID della superficie</p></li><li><p>ID univoco cantonale della superficie / coltura</p></li><li><p>Localizzazione dell’ubicazione</p></li><li><p>Numero d’identificazione del Comune di ubicazione</p></li><li><p>Zona agricola</p></li><li><p>Codice della specie della coltura</p></li><li><p>Caratteristica supplementare della specie</p></li><li><p>Superficie lorda in m2 o per gli alberi numero in pezzi</p></li><li><p>Superficie netta in m2 o per gli alberi numero in pezzi</p></li><li><p>Livello qualitativo della biodiversità</p></li><li><p>Anno in cui è iniziato l’obbligo relativo alla SPB.</p></li><li><p>Superficie con una convenzione secondo la legge sulla protezione della natura e del paesaggio (LPN)</p></li><li><p>Anno in cui è iniziato l’obbligo derivante dalla convenzione LPN.</p></li><li><p>Superficie utilizzata nell’anno di contributzione</p></li><li><p>Superficie avente diritto ai contributi</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('7911d98d-59eb-4cf4-be61-bfe77fe9117e', false, null, NOW(), null, NOW(), '{"de": "Betrieb", "fr": "Exploitation", "it": "Azienda"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Angaben zu Betrieben (von Tierhaltern und Bewirtschaftern), wie: kantonale Betriebsnummer, BUR Nummer, TVD-Nummer, Standortadresse, Koordinaten, Betriebsform, Personenbeziehung des Betriebs, Betriebseigenschaften", "fr": "Ce produit contient des informations générales sur les exploitations des éleveurs et des exploitants, telles que : numéro d’identification cantonal de la forme d’exploitation, numéro REE, numéro BDTA, adresse du site, coordonnées, forme d’exploitation, relation de personnes de l’exploitation, caractérstiques de l’exploitation", "it": "Questo prodotto contiene informazioni concernenti le aziende (detentori di animali e gestori): numero aziendale cantonale, numero RIS, numero BDTA, ubicazione, coordinate, forma di azienda, rapporto tra la persona e l’azienda, farmCharacteristics"}'::jsonb, 'AGIS_API', 'POST', 'register-data/1/register', '{"farmSearchParameters":{"uid":"{{uid}}"}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'register-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=farm&type=farmToFarmRelations&type=personToFarmRelations', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform</p></li><li><p>AGIS_ID_B</p></li><li><p>BUR Nummer</p></li><li><p>UID Nummer des Unternehmens</p></li><li><p>TVD-Nummer</p></li><li><p>Bienenstand-Nummer</p></li><li><p>Eine „parent“ Beziehung eines Betriebes</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>BUR Nummer</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Eine „child“ Beziehung eines Betriebs</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>BUR Nummer</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Die Personenbeziehung eines Betriebs</p><ul><li><p>KT_ID_P Kantonale Identifikationsnummer der Person</p></li><li><p>AGIS_ID_P</p></li><li><p>UID</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Betriebsform</p></li><li><p>Name der Standortgemeinde</p></li><li><p>Offizielle Nummer der Standortgemeinde</p></li><li><p>Kanton der Standortgemeinde</p></li><li><p>Kanton der Datenlieferung</p></li><li><p>Strasse</p></li><li><p>Hausnummer</p></li><li><p>Ort</p></li><li><p>Postleitzahl</p></li><li><p>EGID Eidgenössischer Gebäudeadressidentifikator</p></li><li><p>EGAID Eidgenössischer Gebäudeidentifikator</p></li><li><p>E Koordinate der Betriebsform</p></li><li><p>N Koordinate der Betriebsform</p></li><li><p>Höhe der Betriebsform in m ü. M.</p></li><li><p>Administrative Zonenzugehörigkeit des Betriebs</p></li><li><p>Gebietszugehörigkeit des Betriebs</p></li><li><p>Mutationsdatum</p></li><li><p>Betriebseigenschaften:</p><ul><li><p>Betriebstypologie Agroscope S4-Betriebstypologie ZA2015</p></li><li><p>Landwirtschaftliche Nutzfläche (LN) in m2</p></li><li><p>Anzahl GVE</p></li><li><p>Angabe, ob die Betriebsform Strukturen (Flächen oder Tiere) hat</p></li><li><p>Angabe, ob die Betriebsform Strukturen (Flächen oder Tiere) im Sömmerungsgebiet hat</p></li><li><p>Angabe, ob die Betriebsform grösser ist als die Erhebungsnorm BFS</p></li><li><p>Angabe, ob die Betriebsform Beiträge für die biologische Landwirtschaft nach Direktzahlungsverordnung erhält</p></li><li><p>Angabe, ob die Betriebsform den ÖLN erfüllt (nur für Betriebe mit Direktzahlungen)</p></li><li><p>Angabe, ob die Betriebsform Direktzahlungen (ohne Direktzahlungen für Sömmerungs-betriebe) erhält</p></li><li><p>Angabe, ob die Betriebsform Einzelkulturbeiträge erhält</p></li><li><p>Angabe, ob die Betriebsform Sömmerungsbeiträge erhält</p></li><li><p>Angabe, ob die Betriebsform Insitubeiträge erhält</p></li><li><p>Angabe, ob die Betriebsform Getreidezulage erhält</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Tiergattungsinformationen der Betriebsform:</p><ul><li><p>Status der TVD-Nummer</p></li><li><p>Angabe, ob es sich um einen Bienenstand handelt und wenn ja, ob der Standort besetzt oder unbesetzt ist</p></li><li><p>Angabe, welche Tiere in einer Betriebsform vorkommen</p></li><li><p>Angabe, welche Tiergattungen gehalten werden</p></li><li><p>Mutationsdatum</p></li></ul></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation</p></li><li><p>AGIS_ID_B</p></li><li><p>Numéro REE</p></li><li><p>IDE de l’exploitant</p></li><li><p>Numéro BDTA</p></li><li><p>Numéro du rucher</p></li><li><p>Une relation « parent » d''exploitation</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>Numéro REE</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Une relation « child » d''exploitation</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>Numéro REE</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Personne ayant une relation avec l''exploitation</p><ul><li><p>KT_ID_P Numéro ID cantonal de la personne</p></li><li><p>AGIS_ID_P</p></li><li><p>IDE de de l''entreprise</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Forme d''exploitation</p></li><li><p>Numéro officiel de la commune où se trouve l’exploitation</p></li><li><p>Nom de la commune où se trouve l’exploitation</p></li><li><p>Canton livrant les données</p></li><li><p>Rue</p></li><li><p>Numéro du bâtiment</p></li><li><p>Localité</p></li><li><p>Numéro postal</p></li><li><p>EGID Identificateur fédéral de bâtiment</p></li><li><p>EGAID Identificateur fédéral d''adresse de bâtiment</p></li><li><p>Coordonnée E de la forme d''exploitation</p></li><li><p>Coordonnée N de la forme d''exploitation</p></li><li><p>Hauteur au-dessus du niveau de la mer à laquelle se situe l''exploitation (en m)</p></li><li><p>Zone où se situe l''exploitation</p></li><li><p>Région de l''exploitation</p></li><li><p>Date de mutation</p></li><li><p>Caractéristiques de l’exploitation :</p><ul><li><p>Typologie des exploitations Agroscope S4 ZA2015</p></li><li><p>Surface agricole utile (SAU) en m2</p></li><li><p>Nombre d’UGB</p></li><li><p>Donnée indiquant si la forme d’exploitation présente des structures (surfaces ou animaux)</p></li><li><p>Donnée indiquant si la forme d’exploitation présente des structure (surfaces ou animaux) dans la région d''estivage</p></li><li><p>Donnée indiquant si la forme d’exploitation est plus grande que la norme retenue par l''OFS pour ses enquêtes</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des contributions pour l’agriculture biologique prévues par l’ordonnance sur les paiements directs</p></li><li><p>Donnée indiquant si la forme d’exploitation répond aux règles PER (seulement pour les exploitations recevant des paiements directs)</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des paiements directs (hormis ceux destinés aux exploitations d''estivage)</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des contributions à des cultures particulières</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des contributions d’estivage</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des contributions in situ</p></li><li><p>Donnée indiquant si la forme d’exploitation reçoit des suppléments pour céréales</p></li><li><p>Date de mutation</p></li></ul></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda</p></li><li><p>AGIS_ID_B</p></li><li><p>Numero RIS</p></li><li><p>IDI dell’impresa</p></li><li><p>Numero BDTA</p></li><li><p>Numero dell’apiario</p></li><li><p>Dati di un’azienda «parent»</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>Numero RIS</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Dati di un’azienda «child»</p><ul><li><p>KT_ID_B</p></li><li><p>AGIS_ID_B</p></li><li><p>Numero RIS</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Persona in relazione all’azienda</p><ul><li><p>KT_ID_P Numero d’identificazione cantonale della persona</p></li><li><p>AGIS_ID_P</p></li><li><p>IDI</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Forma di azienda</p></li><li><p>Nome del Comune di ubicazione</p></li><li><p>Numero ufficiale del Comune di ubicazione</p></li><li><p>Cantone del Comune di ubicazione</p></li><li><p>Cantone di fornitura dei dati</p></li><li><p>Via</p></li><li><p>Numero</p></li><li><p>Luogo</p></li><li><p>Numero postale di avviamento</p></li><li><p>EGID Identificatore federale dell''edificio</p></li><li><p>EGAID Identificatore federale di indirizzo dell’edificio</p></li><li><p>Coordinata E della forma di azienda</p></li><li><p>Coordinata N della forma di azienda</p></li><li><p>Altitudine in metri sopra il livello del mare a cui è situata l’azienda</p></li><li><p>Zona in cui è classificata l’azienda</p></li><li><p>Regione in cui è classificata l’azienda</p></li><li><p>Data di mutazione</p></li><li><p>Caratteristiche dell’azienda:</p><ul><li><p>Tipologia di azienda Agroscope S4 AC2015</p></li><li><p>Superficie agricola utile (SAU) in m2</p></li><li><p>Numero di UBG</p></li><li><p>Indicazione se la forma di azienda presenta delle strutture (superfici o animali)</p></li><li><p>Indicazione se la forma di azienda presenta delle strutture (superfici o animali) nella regione d’estivazione</p></li><li><p>Indicazione se le dimensioni della forma di azienda sono superiori alla norma di rilevazione dell’UST</p></li><li><p>Indicazione se la forma di azienda riceve contributi per l’agricoltura biologica secondo l’ordinanza sui pagamenti diretti</p></li><li><p>Indicazione se la forma di azienda adempie la PER (solo per aziende con pagamenti diretti)</p></li><li><p>Indicazione se la forma di azienda riceve pagamenti diretti (senza pagamenti diretti per aziende d’estivazione)</p></li><li><p>Indicazione se la forma di azienda riceve contributi per singole colture</p></li><li><p>Indicazione se la forma di azienda riceve contributi d’estivazione</p></li><li><p>Indicazione se la forma di azienda riceve contributi in situ</p></li><li><p>Indicazione se la forma di azienda riceve supplementi per i cereali</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Informazioni sulle specie animali della forma di azienda:</p><ul><li><p>Stato del numero BDTA</p></li><li><p>Indicazione se si tratta di un apiario e in caso affermativo se questo è occupato o no</p></li><li><p>Indicazione di quali animali sono presenti nella forma di azienda</p></li><li><p>Indicazione di quali specie animali sono detenute</p></li><li><p>Data di mutazione</p></li></ul></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('2375219c-5fe3-458f-bd07-d3c2c87e2539', false, null, NOW(), null, NOW(), '{"de": "Rebflächen Hanglagen", "fr": "Surfaces viticoles en pente", "it": "Vigneti in zone declive"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Rebflächen, die in einem Hang liegen mit einer Neigung grösser als 30%. Die Angaben sind aufgegliedert nach der Zone, Hauptkultur und Betrieb. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient des surfaces viticoles qui se situent dans une pente dont la déclivité est supérieure à 30 %. Les données sont séparées selon la zone, la culture principale et l’exploitation. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti i vigneti con una declività superiore al 30%. I dati sono suddivisi per zona, coltura principale e azienda. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["grapeSurfaceData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=grapeSurfaceData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>ID der Fläche</p></li><li><p>Eindeutige kantonale ID der Fläche / Kultur</p></li><li><p>Lokalisierung des Standortes</p></li><li><p>Identifikationsnummer der Standortgemeinde</p></li><li><p>Landwirtschaftliche Zone</p></li><li><p>Code der Kulturart</p></li><li><p>Netto-Rebfläche mit einer Neigung von 30% bis 50% in m2</p></li><li><p>Netto-Rebfläche mit einer Neigung über 50% in m2</p></li><li><p>Netto-Rebfläche in Terrassen mit einer Neigung über 30 % in m2</p></li><li><p>Fläche mit biologischen Landbau</p></li><li><p>Fläche beitragsberechtigt</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Identifiant de la surface</p></li><li><p>Identifiant cantonal unique de la surface / culture</p></li><li><p>Localisation de l’emplacement</p></li><li><p>Numéro d’identification de la commune d’emplacement</p></li><li><p>Zone agricole</p></li><li><p>Code du genre de culture</p></li><li><p>Surface nette de pente comprise entre 18 % et 35 % en m2</p></li><li><p>Surface nette de pente comprise entre 35 % et 50 % en m2</p></li><li><p>Surface nette de pente supérieure à 50 % en m2</p></li><li><p>Ce flag indique qu’une surface a été utilisée / exploitée ou non l’année en question</p></li><li><p>Ce flag concerne le droit aux contributions aux surfaces</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>ID della superficie</p></li><li><p>ID univoco cantonale della superficie / coltura</p></li><li><p>Localizzazione dell’ubicazione</p></li><li><p>Numero d’identificazione del Comune di ubicazione</p></li><li><p>Zona agricola</p></li><li><p>Codice della specie della coltura</p></li><li><p>Superficie netta con una declività compresa tra il 18% e il 35% in m2</p></li><li><p>Superficie netta con una declività compresa tra il 35% e il 50% in m2</p></li><li><p>Superficie netta con una declività di oltre il 50% in m2</p></li><li><p>Superficie sfalciata o utilizzata a scopo campicolo nell’anno di contribuzione</p></li><li><p>Superficie avente diritto ai contributi</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('0a808700-d89e-4fa0-a2b8-8edb15f3addd', false, null, NOW(), null, NOW(), '{"de": "Flächen Hauptkulturen", "fr": "Surfaces de cultures principales", "it": "Superfici delle colture principali"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Fläche der im entsprechenden Jahr angebauten Hauptkulturen eines Betriebs inklusive Angabe zur landwirtschaftlichen Zone, Standortgemeinde und der Produktionsform (z.B. Einsatz von Pflanzenschutzmitteln, Bio). In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient la surface des cultures principales de l’année correspondante dans l’exploitation, y compris l’indication de la zone agricole, de la commune d’implantation et de la forme d’exploitation (utilisation de produits phytosanitaires, Bio). Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti le superfici sulle quali nell’anno in questione sono state coltivate le colture principali di un’azienda, incluse le informazioni concernenti la zona agricola, il Comune di ubicazione e la forma di produzione (p.es. utilizzo di prodotti fitosanitari, bio). Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["generalSurfaceData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=generalSurfaceData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>ID der Fläche</p></li><li><p>Eindeutige kantonale ID der Fläche / Kultur des betreffenden Polygons aus dem Geodatenmodell</p></li><li><p>Lokalisierung des Standortes</p></li><li><p>Identifikationsnummer der Standortgemeinde</p></li><li><p>Landwirtschaftliche Zone</p></li><li><p>Code der Kulturart der Hauptkultur</p></li><li><p>Zusätzliche Ausprägung der Kulturart</p></li><li><p>Bruttofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Nettofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Angabe, ob die Fläche im Beitragsjahr genutzt wurde</p></li><li><p>Fläche mit einem Vertrag gemäss Natur- und Heimatschutzgesetz (NHG)</p></li><li><p>Fläche in schonender Bodenbearbeitung</p></li><li><p>Auf Pflanzenschutzmittel im Ackerbau verzichtet</p></li><li><p>Auf Insektizide und Akarizide im Gemüse und Beerenanabau verzichtet</p></li><li><p>Auf Insektizide, Akarizide und Fungizide nach der Blüte bei Dauerkulturen verzichtet</p></li><li><p>Nur Hilfsmittel nach der biologischen Landwirtschaft verwendet</p></li><li><p>Auf Herbizide im Ackerbau und in Spezialkulturen verzichtet</p></li><li><p>Fläche mit biologischem Landbau</p></li><li><p>Fläche grundsätzlich beitragsberechtigt</p></li><li><p>Fläche für die Einzelkulturbeiträge oder die Getreidezulage beitragsberechtigt</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Identifiant de la surface</p></li><li><p>Identifiant cantonal unique de la surface / culture</p></li><li><p>Localisation de l’emplacement</p></li><li><p>Numéro d’identification de la commune d’emplacement</p></li><li><p>Zone agricole</p></li><li><p>Code du genre de culture</p></li><li><p>Caractéristique supplémentaire du genre de culture</p></li><li><p>Surface brute en m2 ou pour les arbres, leur nombre</p></li><li><p>Surface nette en m2 ou pour les arbres, leur nombre</p></li><li><p>Ce flag se réfère au fait qu’une surface a été utilisée / exploitée ou non l’année en question.</p></li><li><p>Transmettre un flag avec 1 dans le cas des surfaces pour lesquelles il existe un contrat LPN ou une base légale cantonale</p></li><li><p>La surface est-elle exploitée avec des techniques culturales préservant le sol ?</p></li><li><p>A-t-on renoncé pour cette surface aux moyens phytosanitaires utilisés dans les grandes cultures ?</p></li><li><p>Avait-on renoncé pour cette surface aux insecticides et aux acaricides utilisés dans les cultures maraîchères et dans la culture de petits fruits ?</p></li><li><p>Avait-on renoncé aux insecticides, aux acaricides et aux fongicides utilisés dans les cultures pérennes après la floraison ?</p></li><li><p>N’a-t-on utilisé pour cette culture pérenne que des produits phytosanitaires et / ou des organismes utiles conformes à l’agriculture biologique ?</p></li><li><p>A-t-on renoncé pour cette surface aux herbicides utilisés dans les grandes cultures et dans les cultures spéciales ?</p></li><li><p>Donnée indiquant s’il s’agit d’une surface d’agriculture biologique.</p></li><li><p>Indique si la surface donne droit en principe à des contributions</p></li><li><p>Donnée indiquant si la surface donne droit aux contributions à des cultures particulières ou au supplément pour les céréales.</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>ID della superficie</p></li><li><p>ID univoco cantonale della superficie / coltura del rispettivo poligono del modello di geodati</p></li><li><p>Localizzazione dell’ubicazione</p></li><li><p>Numero d’identificazione del Comune di ubicazione</p></li><li><p>Zona agricola</p></li><li><p>Codice della specie della coltura principale</p></li><li><p>Caratteristica supplementare della specie</p></li><li><p>Superficie lorda in m2 o per gli alberi numero in pezzi</p></li><li><p>Superficie netta in m2 o per gli alberi numero in pezzi</p></li><li><p>Indicazione se la superficie è stata utilizzata nell’anno di contribuzione</p></li><li><p>Superficie con una convenzione secondo la legge sulla protezione della natura e del paesaggio (LNP)</p></li><li><p>Superficie con lavorazione rispettosa del suolo</p></li><li><p>Rinuncia a prodotti fitosanitari in campicoltura?</p></li><li><p>Rinuncia a insetticidi e acaricidi in orticoltura e nella coltivazione di bacche?</p></li><li><p>Rinuncia a insetticidi, acaricidi e fungicidi dopo la fioritura nelle colture perenni</p></li><li><p>Utilizzo esclusivo di mezzi ausiliari conformi all’agricoltura biologica</p></li><li><p>Rinuncia a erbicidi in campicoltura e nelle colture speciali</p></li><li><p>Superficie con agricoltura biologica</p></li><li><p>Superficie avente di norma diritto a contributi</p></li><li><p>Superficie avente diritto ai contributi per singole colture o al supplemento per i cereali</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('c661ea48-106d-4d7a-a5d1-a9a6db48dd8c', false, null, NOW(), null, NOW(), '{"de": "Person", "fr": "Personne", "it": "Persona"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Angaben zur Person (Tierhalter und Bewirtschafter), wie: Name, Vorname, kantonale Personennummer, UID, Rechtsform, Postadresse, Telefon, Email und die Identifikationsnummer des dazugehörigen Betriebs.", "fr": "Ce produit contient des informations personnelles sur les éleveurs et les exploitants, telles que : nom, prénom, numéro personnel cantonal, IDE, forme juridique, adresse postale, téléphone et e-mail, ainsi que l’exploitation appartenant à la personne", "it": "Questo prodotto contiene informazioni concernenti la persona (detentore di animali e gestore)e: cognome, nome, numero personale cantonale, IDI, forma giuridica, indirizzo postale, telefono, e-mail e numero di identificazione dell''azienda corrispondente."}'::jsonb, 'AGIS_API', 'POST', 'register-data/1/register', '{"personSearchParameters":{"uid":"{{uid}}"}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'register-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=person&type=personToPersonRelations&type=personToFarmRelations', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person</p></li><li><p>AGIS_ID_P</p></li><li><p>UID des Unternehmens</p></li><li><p>Daten einer „parent“ Person</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>UID</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Daten einer „child“ Person</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>UID</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Betrieb, der eine Beziehung mit der Person hat</p><ul><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform</p></li><li><p>AGIS_ID_B</p></li><li><p>BUR-Nummer</p></li><li><p>Mutationsdatum</p></li></ul></li><li><p>Berufliche Haupttätigkeit</p></li><li><p>Rechtsform der Person</p></li><li><p>Geburtsdatum</p></li><li><p>Jahrgang</p></li><li><p>Korrespondenzsprache</p></li><li><p>Wohnsitzgemeinde</p></li><li><p>Offizielle Nummer der Wohnsitzgemeinde</p></li><li><p>Kanton der Wohnsitzgemeinde</p></li><li><p>Kanton der Datenlieferung</p></li><li><p>Organisation:</p><ul><li><p>Name Organisation</p></li></ul></li><li><p>Natürliche Person:</p><ul><li><p>Vorname der natürlichen Person</p></li><li><p>Nachname der natürlichen Person</p></li><li><p>Anrede</p></li><li><p>Strasse</p></li><li><p>Hausnummer</p></li><li><p>Postfachnummer</p></li><li><p>Ort</p></li><li><p>Postleitzahl</p></li></ul></li><li><p>Eidgenössischer Gebäudeadressidentifikator</p></li><li><p>E-Mail Adresse</p></li><li><p>Telefonnummer</p></li><li><p>Mutationsdatum</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>KT_ID_P Numéro ID cantonal de la personne</p></li><li><p>AGIS_ID_P</p></li><li><p>IDE de de l''entreprise</p></li><li><p>Données d''une personne « parent »</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>IDE</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Données d''une personne « child »</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>IDE</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Entreprise ayant une relation avec la personne</p><ul><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation</p></li><li><p>AGIS_ID_B</p></li><li><p>Numéro REE</p></li><li><p>Date de mutation</p></li></ul></li><li><p>Activité professionnelle principale</p></li><li><p>Forme juridique de la personne</p></li><li><p>Date de naissance</p></li><li><p>Année</p></li><li><p>Langue de communication</p></li><li><p>Nom de la commune de domicile</p></li><li><p>Numéro officiel de la commune de domicile</p></li><li><p>Canton de la commune de résidence</p></li><li><p>Canton de livraison des données</p></li><li><p>Organisation:</p><ul><li><p>Nom de l’organisation</p></li></ul></li><li><p>Personne physique:</p><ul><li><p>Prénom de la personne physique</p></li><li><p>Nom de famille de la personne physique</p></li><li><p>Civilité de la personne</p></li><li><p>Rue</p></li><li><p>Numéro du bâtiment</p></li><li><p>Numéro de la case postale</p></li><li><p>Localité</p></li><li><p>Numéro postal</p></li></ul></li><li><p>Identificateur fédéral d''adresse de bâtiment</p></li><li><p>Adresse électronique</p></li><li><p>Numéro de téléphone</p></li><li><p>Date de mutation</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>KT_ID_P Numero d’identificazione cantonale del gestore</p></li><li><p>AGIS_ID_P</p></li><li><p>IDI dell’impresa</p></li><li><p>Dati di una persona «parent»</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>IDI</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Dati di una persona «child»</p><ul><li><p>KT_ID_P</p></li><li><p>AGIS_ID_P</p></li><li><p>IDI</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Azienda in relazione alla persona</p><ul><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda</p></li><li><p>AGIS_ID_B</p></li><li><p>Numero RIS</p></li><li><p>Data di mutazione</p></li></ul></li><li><p>Attività professionale principale</p></li><li><p>Forma giuridica della persona</p></li><li><p>Data di nascita</p></li><li><p>Anno</p></li><li><p>Lingua di corrispondenza</p></li><li><p>Comune di domicilio</p></li><li><p>Numero ufficiale del Comune di domicilio</p></li><li><p>Cantone del Comune di domicilio</p></li><li><p>Cantone di fornitura dei dati</p></li><li><p>Organizzazione:</p><ul><li><p>Nome dell’organizzazione</p></li></ul></li><li><p>Persona fisica:</p><ul><li><p>Nome della persona fisica</p></li><li><p>Cognome della persona fisica</p></li><li><p>Appellativo</p></li><li><p>Via</p></li><li><p>Numero</p></li><li><p>Casella postale</p></li><li><p>Luogo</p></li><li><p>Numero postale di avviamento</p></li></ul></li><li><p>Identificatore federale dell''edificio</p></li><li><p>E-mail</p></li><li><p>Telefono</p></li><li><p>Data di mutazione</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('ef4f42dd-eaa9-4af1-988c-86b47bd963fe', false, null, NOW(), null, NOW(), '{"de": "Flächen Hanglagen", "fr": "Surfaces en pente", "it": "Superfici in zone declive"}'::jsonb, '{"de": "Dieses Datenprodukt enthält Flächen, die in einem Hang liegen mit einer Neigung grösser als 18%. Die Angaben sind aufgegliedert nach der Zone, Hauptkultur und Betrieb. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient des surfaces qui se situent dans une pente dont la déclivité est supérieure à 18 %. Les données sont séparées selon la zone, la culture principale et l’exploitation. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti le superfici in zone con una declività superiore al 18%. I dati sono suddivisi per zona, coltura principale e azienda. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["slopeSurfaceData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=slopeSurfaceData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>ID der Fläche</p></li><li><p>Eindeutige kantonale ID der Fläche / Kultur</p></li><li><p>Lokalisierung des Standortes</p></li><li><p>Identifikationsnummer der Standortgemeinde</p></li><li><p>Landwirtschaftliche Zone</p></li><li><p>Code der Kulturart</p></li><li><p>Nettofläche mit einer Neigung von 18% bis 35% in m2</p></li><li><p>Nettofläche mit einer Neigung von 35% bis 50% in m2</p></li><li><p>Nettofläche mit einer Neigung über 50% in m2</p></li><li><p>Fläche im Beitragsjahr gemäht oder ackerbaulich genutzt</p></li><li><p>Fläche beitragsberechtigt</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Identifiant de la surface</p></li><li><p>Identifiant cantonal unique de la surface / culture</p></li><li><p>Localisation de l’emplacement</p></li><li><p>Numéro d’identification de la commune d’emplacement</p></li><li><p>Zone agricole</p></li><li><p>Code du genre de culture</p></li><li><p>Surface nette de pente comprise entre 18 % et 35 % en m2</p></li><li><p>Surface nette de pente comprise entre 35 % et 50 % en m2</p></li><li><p>Surface nette de pente supérieure à 50 % en m2</p></li><li><p>Ce flag indique qu’une surface a été utilisée / exploitée ou non l’année en question</p></li><li><p>Ce flag concerne le droit aux contributions aux surfaces</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>ID della superficie</p></li><li><p>ID univoco cantonale della superficie / coltura</p></li><li><p>Localizzazione dell’ubicazione</p></li><li><p>Numero d’identificazione del Comune di ubicazione</p></li><li><p>Zona agricola</p></li><li><p>Codice della specie della coltura</p></li><li><p>Superficie viticola netta con declività compresa tra il 30% e il 50% in m2</p></li><li><p>Superficie viticola netta con declività di oltre il 50% in m2</p></li><li><p>Superficie viticola terrazzata netta con declività di oltre il 30% in m2</p></li><li><p>Superficie con agricoltura biologica</p></li><li><p>Superficie avente diritto ai contributi</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('085e4b72-964d-4bd5-a3c9-224d8c5585af', false, null, NOW(), null, NOW(), '{"de": "Nutztiere auf Betrieb", "fr": "Animaux de rente dans l’exploitation", "it": "Animali da reddito nell’azienda"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Art und Anzahl Nutztiere, die auf einem Betrieb im Vorjahr gehalten wurden. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient l’espèce et le nombre d’animaux de rente qui sont détenus dans l’exploitation. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti gli animali da reddito (specie e numero) detenuti nell’azienda. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["animalData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=animalData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer des Tierstandorts</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>Tierkategorie</p></li><li><p>Daten aus der TVD</p><ul><li><p>Gesamter Bestand der Tierkategorie im Vorjahr</p></li><li><p>Summe der Anzahl GVE auf dem Tierstandort sowie der Sömmerung im Inland und angestammten Flächen im Ausland (im Vorjahr)</p></li><li><p>Anzahl Tiere am Stichtag</p></li><li><p>Durchschnittliche Anzahl Tiere (Vorjahr)</p></li><li><p>Anzahl GVE (Vorjahr) (gezählte Tiertage / Anzahl Tage des Jahres*GVE-Faktor)</p></li><li><p>GVE der im Inland gesömmerten Tiere</p></li><li><p>Normalstösse der im Inland gesömmerten Tiere</p></li><li><p>GVE der gesömmerten Tiere (auf angestammten Sömmerungsbetrieben in der ausländischen Grenzzone)</p></li></ul></li><li><p>Daten aus der Selbstdeklaration</p><ul><li><p>Anzahl Tiere am Stichtag</p></li><li><p>Durchschnittliche Anzahl Tiere (Vorjahr)</p></li><li><p>Haltungsform für Schweine und Geflügel</p></li><li><p>Anzahl gesömmerte Tiere (Vorjahr)</p></li><li><p>Sömmerungsdauer in Anzahl Tagen (Vorjahr)</p></li></ul></li><li><p>Besonders tierfreundliche Produktionsform (nur für Betriebe mit Direktzahlungen)</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE du lieu où sont gardés les animaux</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne gérant l’exploitation principale</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Catégorie d’animaux</p></li><li><p>Données BDTA</p><ul><li><p>Cheptel total de la catégorie d’animaux l’année précédente</p></li><li><p>Somme des UGB de l’exploitation à l’année, de l’estivage en Suisse et dans des exploitations d’estivage traditionnelles de la zone frontière (l’année précédente).</p></li><li><p>Cheptel de la catégorie d’animaux du jour de référence</p></li><li><p>Nombre d’animaux sur l’exploitation selon les données BDTA</p></li><li><p>Nombre d’UGB sur l’exploitation selon les données BDTA.</p></li><li><p>Somme des jours / jours de l’année * facteur UGB</p></li><li><p>Nombre d’UGB estivés en Suisse selon les données BDTA</p></li><li><p>Nombre de pâquiers normaux des animaux estivés en Suisse selon les données BDTA</p></li><li><p>Nombre d’UGB estivés dans des exploitations d’estivage traditionnelles de la zone frontière selon les données BDTA</p></li></ul></li><li><p>Données du recensement</p><ul><li><p>Cheptel de la catégorie d’animaux du jour de référence</p></li><li><p>Cheptel moyen de la catégorie d’animaux en nombre de têtes pour l’année précédente</p></li><li><p>Mode de garde pour les porcs et la volaille.</p></li><li><p>Nombre d’animaux estivés au cours de l’année précédente</p></li><li><p>Durée d’estivage de l’année précédente en jours</p></li></ul></li><li><p>Formes de production particulièrement respectueuses des animaux (seulement pour les exploitations recevant des paiements directs)</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS dell’ubicazione degli animali</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>Categoria animale</p></li><li><p>Dati della BDTA</p><ul><li><p>Effettivo totale della categoria animale nell’anno precedente</p></li><li><p>Somma delle UBG nell’ubicazione degli animali, nell’estivazione all’interno del Paese e sulle superfici coltivate per tradizione familiare nella zona di confine estera (anno precedente)</p></li><li><p>Numero di animali nel giorno di riferimento</p></li><li><p>Numero medio di animali (anno precedente)</p></li><li><p>Numero di UBG (anno precedente) (giorni conteggiati per animale / numero di giorni dell’anno*coefficiente UBG)</p></li><li><p>UBG di animali estivati all’interno del Paese</p></li><li><p>Carichi normali di animali estivati all’interno del Paese</p></li><li><p>UBG di animali estivati (su superfici coltivate per tradizione familiare nella zona di confine estera)</p></li></ul></li><li><p>Dati dell’autodichiarazione</p><ul><li><p>Numero di animali nel giorno di riferimento</p></li><li><p>Numero medio di animali (anno precedente)</p></li><li><p>Forma di detenzione per suini e pollame</p></li><li><p>Numero di animali estivati (anno precedente)</p></li><li><p>Durata dell’estivazione in giorni (anno precedente)</p></li></ul></li><li><p>Forma di produzione particolarmente rispettosa degli animali (solo per aziende con pagamenti diretti)</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('1dad9f91-30d8-45c9-8c82-ad72f4cb22e7', false, null, NOW(), null, NOW(), '{"de": "Vernetzungsflächen", "fr": "Surfaces de mise en réseau", "it": "Superfici di interconnessione"}'::jsonb, '{"de": "Dieses Datenprodukt enthält die Vernetzungsflächen gemäss Direktzahlungsverordnung (DZV). Die Angaben sind aufgegliedert nach der Zone, Hauptkultur und Betrieb. In dem Datenprodukt werden auch Angaben zum Betrieb und zur Person bereitgestellt.", "fr": "Ce produit contient les données sur les surfaces de mise en réseau selon l’ordonnance sur les paiements directs (OPD). Les données sont séparées selon la zone, la culture principale et l’exploitation. Ce produit contient aussi des indications sur l’exploitation et la personne.", "it": "Questo prodotto contiene informazioni concernenti le superfici di interconnessione secondo l’ordinanza sui pagamenti diretti (OPD). I dati sono suddivisi per zona, coltura principale e azienda. Nel prodotto di dati sono fornite anche informazioni sull’azienda e sulla persona."}'::jsonb, 'AGIS_API', 'POST', 'structure-data/1/structure', '{"surveyYear":"{{year}}","ids":{"uid":"{{uid}}"},"dataTypes":{"structureType":["networkSurfaceData"]},"dataRequestType":{"finalData":false}}', 'UID_BASED_PRE_VALIDATION', '5335d715-e95c-4777-a424-ab73f2ff5618', null, 'structure-data/2/uids-with-changes?since={{LAST_CHANGED_SINCE_DATE_TIME}}&type=networkSurfaceData', 'b1398c9d-c28d-4e7e-b5f0-f5d615a6471c', 'ACTIVE', 'CHE113614519', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>Datum der Erfassung bzw. der letzten Änderung dieses Datensatzes im kantonalen System</p></li><li><p>KT_ID_B Kantonale Identifikationsnummer der Betriebsform auf der Stufe, auf der die nachfolgenden Daten erfasst wurden</p></li><li><p>BUR-Nummer</p></li><li><p>KT_ID_P Kantonale Identifikationsnummer der bewirtschaftenden Person des Hauptbetriebs</p></li><li><p>UID des Unternehmens</p></li><li><p>Angaben zum Betrieb, wie in Datenprodukt “Betrieb”, ohne Beziehungen zu Betrieben</p></li><li><p>Angaben zur Person, wie in Datenprodukt “Person”, ohne Beziehungen zu Personen</p></li><li><p>Betriebseigenschaften, wie in Datenprodukt “Betrieb”</p></li><li><p>ID der Fläche</p></li><li><p>Eindeutige kantonale ID der Fläche / Kultur</p></li><li><p>Lokalisierung des Standortes</p></li><li><p>Identifikationsnummer der Standortgemeinde</p></li><li><p>Landwirtschaftliche Zone</p></li><li><p>Code der Kulturart</p></li><li><p>Zusätzliche Ausprägung der Kulturart</p></li><li><p>Bruttofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Nettofläche in m2 bzw. bei Bäumen die Anzahl in Stück</p></li><li><p>Jahr, in welchem die Verpflichtung zur Vernetzung begonnen hat.</p></li><li><p>Organisation, welche einen Beitrag an die Fläche leistet</p></li><li><p>Namen der Organisation</p></li><li><p>Beitragsansatz des Bundes verwendet</p></li><li><p>Beitragsansatz der Organisation in CHF pro ha oder pro Baum bzw. Element</p></li><li><p>Fläche beitragsberechtigt</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Date resp. la saisie ou la dernière modification du jeu de données dans le système cantonal</p></li><li><p>KT_ID_B Numéro cantonal de la forme d’exploitation au niveau de laquelle les données suivantes ont été saisies</p></li><li><p>Numéro REE</p></li><li><p>KT_ID_P Numéro ID cantonal de la personne</p></li><li><p>Numéro IDE</p></li><li><p>Indications sur l’exploitation, comme dans le produit « Exploitation », sans relations vers les exploitations</p></li><li><p>Indications sur la personne, comme dans le produit « Personne », sans relations vers les personnes</p></li><li><p>Caractéristiques de l’exploitation, comme dans le produit « Exploitation »</p></li><li><p>Identifiant de la surface</p></li><li><p>Identifiant cantonal unique de la surface / culture</p></li><li><p>Localisation de l’emplacement</p></li><li><p>Numéro d’identification de la commune d’emplacement</p></li><li><p>Zone agricole</p></li><li><p>Code du genre de culture</p></li><li><p>Caractéristique supplémentaire du genre de culture</p></li><li><p>Surface brute en m2 ou pour les arbres, leur nombre</p></li><li><p>Surface nette en m2 ou pour les arbres, leur nombre</p></li><li><p>Année de début d’engagement de mise réseau</p></li><li><p>Nom de l’organisation qui verse des contributions aux surfaces</p></li><li><p>Indique si le taux de coontribution de la Confédération est utilisé</p></li><li><p>Taux de contribution de l’organisation en CHF par ha ou par arbre / élément</p></li><li><p>Ce flag concerne le droit aux contributions des surfaces SPB</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>Data di registrazione o dell’ultima modifica di questo set di dati nel sistema cantonale</p></li><li><p>KT_ID_B Numero d’identificazione cantonale della forma di azienda al livello a cui sono stati registrati i dati seguenti:</p></li><li><p>Numero RIS</p></li><li><p>KT_ID_P Numero d’identificazione cantonale del gestore dell’azienda principale</p></li><li><p>IDI dell’impresa</p></li><li><p>Indicazioni sull’azienda come nel prodotto «Azienda», senza relazioni rispetto all’azienda</p></li><li><p>Indicazioni sulla persona come nel prodotto «Persona», senza relazioni rispetto alla persona</p></li><li><p>Caratteristiche dell’azienda come nel prodotto «Azienda»</p></li><li><p>ID della superficie</p></li><li><p>ID univoco cantonale della superficie / coltura</p></li><li><p>Localizzazione dell’ubicazione</p></li><li><p>Numero d’identificazione del Comune di ubicazione</p></li><li><p>Zona agricola</p></li><li><p>Codice della specie della coltura</p></li><li><p>Caratteristica supplementare della specie</p></li><li><p>Superficie lorda in m2 o per gli alberi numero in pezzi</p></li><li><p>Superficie netta in m2 o per gli alberi numero in pezzi</p></li><li><p>Anno in cui è cominciato l’obbligo relativo all’interconnessione</p></li><li><p>Organizzazione che dà un contributo alla superficie</p></li><li><p>Nome dell’organizzazione</p></li><li><p>Aliquota di contributo della Confederazione applicata</p></li><li><p>Aliquota di contributo dell’organizzazione in CHF per ha o per albero o elemento</p></li><li><p>Superficie avente diritto a contributi</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
