    ('b17ae68a-42a8-47fe-ba7b-ec7105c5c5c7', false, null, NOW(), null, NOW(), '{"de": "Bewirtschafterdaten", "fr": "Données relatives à l’exploitant", "it": "Dati sull’allevatore"}'::jsonb, '{"de": "Dieses Datenpaket enthält den aktuellen Bewirtschafter für eine spezifische TVD-Nummer / BUR-Nummer. Es umfasst Daten der Rechtspersönlichkeit (natürliche oder juristische Person) sowie deren Kontaktdaten.", "fr": "Ce paquet de données contient les informations relatives à l’exploitant actuel pour un numéro BDTA/REE spécifique. Il comprend les données relatives à la personnalité juridique (personne physique ou morale) ainsi que ses coordonnées.", "it": "Questo pacchetto di dati contiene l’allevatore attuale per un numero BDTA/numero RIS specifico. Comprende i dati relativi alla personalità giuridica (persona fisica o giuridica) e i relativi recapiti."}'::jsonb, 'TVD_ANIMAL_TRACING_API', 'GET', 'v1.0/customer/shared-data/localunits/{{bur}}/legalunit?dataPackage=TVD_FarmManagerV1&recipientUid={{recipientUid}}', null, 'BUR_BASED_POST_VALIDATION', '4ccbfa06-a547-4a76-9dfc-61c22a4ea8ce', null, null, '1c438fa1-1112-4ee9-b1af-2d96acf385f0', 'ACTIVE', 'CHE105031830', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>UID</p></li><li><p>Hauptadresse</p></li><li><p>Strasse</p></li><li><p>Hausnummer</p></li><li><p>PLZ</p></li><li><p>Stadt</p></li><li><p>Land</p></li><li><p>Korrespondenzsprache</p></li><li><p>Aktiv</p></li><li><p>E-Mail Adresse</p></li><li><p>E-Mail Adresse</p></li><li><p>Nachname</p></li><li><p>Vorname</p></li><li><p>Name</p></li><li><p>Name Zusatz 1</p></li><li><p>Name Zusatz 2</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>IDE</p></li><li><p>Adresse principale</p></li><li><p>Rue</p></li><li><p>Numéro de maison</p></li><li><p>NPA</p></li><li><p>Ville</p></li><li><p>Pays</p></li><li><p>Langue de correspondance</p></li><li><p>Actif</p></li><li><p>Adresse e-mail</p></li><li><p>Adresse e-mail</p></li><li><p>Nom</p></li><li><p>Prénom</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><ul><li><p>IDI</p></li><li><p>Indirizzo principale</p></li><li><p>Via</p></li><li><p>numero civico</p></li><li><p>CAP</p></li><li><p>Luogo</p></li><li><p>Paese</p></li><li><p>Lingua di corrispondenza</p></li><li><p>Attivo</p></li><li><p>E-mail</p></li><li><p>E-mail</p></li><li><p>Cognome</p></li><li><p>Nome</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('3e0bfd53-94c7-4a73-8d71-0f2c64313c3f', false, null, NOW(), null, NOW(), '{"de": "Equidendetail Zucht", "fr": "Informations sur les équidés - élevage", "it": "Dettagli degli equidi dell’allevamento"}'::jsonb, '{"de": "Dieses Datenpaket enthält die Equidendaten für eine spezifische UELN. Es umfasst die Basisinformationen des abgefragten Tieres. Zusätzlich werden Angaben zu Eigentümer, Eltern, Aufenthalten, Signalement, Nachkommen und Passdaten geliefert. Das Datenpaket ist den Equiden Zuchtorganisationen vorbehalten.", "fr": "Ce paquet de données contient les informations relatives aux équidés pour un UELN spécifique. Il comprend les informations de base sur l’animal recherché. Des informations sur les propriétaires, les parents, les séjours, les signalements, les descendants et les données du passeport sont également fournies. Ce paquet de données est réservé aux organisations d’élevage d’équidés.", "it": "Questo pacchetto di dati contiene i dati relativi agli equidi per un numero UELN specifico. Comprende le informazioni di base dell’animale consultato. Vengono inoltre fornite informazioni su proprietari, parenti, soggiorni, segnalamenti, discendenti e dati del passaporto. Il pacchetto di dati è riservato alle organizzazioni d’allevamento degli equidi."}'::jsonb, 'TVD_ANIMAL_TRACING_API', 'GET', 'v1.0/equid/shared-data/equids/{{ueln}}?dataPackage=TVD_EquidDetailBreedingV1&recipientUid={{recipientUid}}', null, 'UNBOUND_UID_BASED_POST_VALIDATION', '4ccbfa06-a547-4a76-9dfc-61c22a4ea8ce', null, null, '1c438fa1-1112-4ee9-b1af-2d96acf385f0', 'ACTIVE', 'CHE105031830', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:<br>Equide</p><ul><li><p>UELN</p></li><li><p>Mikrochipnummer</p></li><li><p>Tiername</p></li><li><p>Geschlecht</p></li><li><p>Kastriert</p></li><li><p>Nutzungsart</p></li><li><p>Geburtsdatum</p></li><li><p>Geburtsort</p></li><li><p>Rasse</p></li><li><p>Art</p></li><li><p>Widerristhöhe</p></li><li><p>Farbe</p></li><li><p>Farbe Freitext<