    ('e08af9d2-99ec-41b3-a77c-d4457415944f', false, null, NOW(), null, NOW(), '{"de": "Tierhaltungsdaten", "fr": "Données relatives à l’élevage", "it": "Dati sull’azienda"}'::jsonb, '{"de": "Dieses Datenpaket enthält Tierhaltungsdaten für eine spezifische TVD-Nummer / BUR-Nummer. Es umfasst Adresse und andere betriebsspezifische Daten der Tierhaltung.", "fr": "Ce paquet de données contient des informations relatives à l’élevage pour un numéro BDTA/REE spécifique. Il comprend l’adresse et d’autres informations spécifiques à l’exploitation relatives à l’élevage.", "it": "Questo pacchetto di dati contiene i dati relativi all’azienda per un numero BDTA/numero RIS specifico. Comprende l’indirizzo e altri dati specifici dell’azienda."}'::jsonb, 'TVD_ANIMAL_TRACING_API', 'GET', 'v1.0/customer/shared-data/localunits/{{bur}}?dataPackage=TVD_FarmDataV1&recipientUid={{recipientUid}}', null, 'BUR_BASED_POST_VALIDATION', '4ccbfa06-a547-4a76-9dfc-61c22a4ea8ce', null, null, '1c438fa1-1112-4ee9-b1af-2d96acf385f0', 'ACTIVE', 'CHE105031830', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><ul><li><p>BUR-Nummer</p></li><li><p>TVD-Nummer</p></li><li><p>Unternehmens-Identifikationsnummer</p></li><li><p>Betriebsform</p></li><li><p>Name</p></li><li><p>Zuständiger Kanton</p></li><li><p>Kanton des Wohnsitzes</p></li><li><p>Hauptadresse</p></li><li><p>Strasse</p></li><li><p>Hausnummer</p></li><li><p>PLZ</p></li><li><p>Stadt</p></li><li><p>Land</p></li><li><p>Postfach Nummer</p></li><li><p>Postfach Text</p></li><li><p>zu Handen von</p></li><li><p>Aktiv</p></li><li><p>VTNP Datum</p></li><li><p>Ost (Y)</p></li><li><p>Nord (X)</p></li><li><p>Höhe</p></li><li><p>Gebiet</p></li><li><p>Zone</p></li><li><p>BVD-Status</p></li><li><p>Moderhinkestatus</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises :</p><ul><li><p>Numéro REE</p></li><li><p>Numéro BDTA</p></li><li><p>Numéro d’identification des entreprises</p></li><li><p>Forme d''exploitation<