    ('4e09edca-a52c-4455-9933-57319fddc6be', false, null, NOW(), null, NOW(), '{"de": "GVE-Werte Bison", "fr": "Valeurs UGB bisons", "it": "Valori UBG bisonti"}'::jsonb, '{"de": "Mit der Freigabe dieses Pakets werden die Tierhaltungsdaten sowie die Daten des GVE-Berichts für Bison übermittelt.\n\nUnter dem Menüpunkt «Links und Dokumente» finden Sie einen Beispielbericht, anhand dessen Sie einen detaillierten Einblick in die enthaltenen Daten erhalten.", "fr": "Avec la validation de ce paquet, les données de détention des animaux ainsi que les données du rapport UGB pour les bisons sont transmises.\n\nSous le point de menu « Liens et documents », vous trouverez un rapport d’exemple qui vous permettra d’avoir un aperçu détaillé des données qu’il contient.", "it": "Con l''approvazione di questo pacchetto vengono trasmessi i dati sulla detenzione degli animali nonché i dati del rapporto UBG per i bisonti.\n\nAlla voce di menu « Link e documenti » troverete un rapporto di esempio che vi permetterà di avere una visione dettagliata dei dati in esso contenuti."}'::jsonb, 'TVD_ANIMAL_TRACING_API', null, '', '', null, '4ccbfa06-a547-4a76-9dfc-61c22a4ea8ce', null, '', '1c438fa1-1112-4ee9-b1af-2d96acf385f0', 'ACTIVE', 'CHE105031830', false, null, '{"de": "", "fr": "", "it": ""}'::jsonb, '[]'::jsonb),
