    ('59115547-cfd5-428a-9863-6cd1b2200013', false, null, NOW(), null, NOW(), '{"de": "Tierhaltungsdaten", "fr": "Données relatives à l’élevage", "it": "Dati sull’azienda"}'::jsonb, '{"de": "Dieses Datenpaket enthält Tierhaltungsdaten für eine spezifische BUR-Nr. Es umfasst die Adresse und andere betriebsspezifische Daten der Tierhaltung.", "fr": "Ce paquet de données contient les informations relatives à l’élevage pour un REE spécifique. Il comprend l’adresse et d’autres informations spécifiques à l’exploitation relatives à l’élevage.", "it": "Questo pacchetto di dati contiene i dati relativi all’azienda per un numero RIS specifico. Comprende l’indirizzo e altri dati specifici dell’azienda."}'::jsonb, 'TVD_ZO_API', 'GET', 'api-zo/v1.0/shared-data/localunits/{{bur}}?dataPackage=ZOAPI_FarmDataV1&recipientUid={{recipientUid}}', null, 'BUR_BASED_POST_VALIDATION', 'e93f1023-850d-4188-bf40-50e5eedaaa57', null, null, 'cadf12a3-af55-4919-8d30-6849ab6c13ba', 'ACTIVE', 'CHE105031830', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><p><br></p><ul><li><p>BUR-Nummer</p></li><li><p>TVD-Nummer</p></li><li><p>Unternehmens-Identifikationsnummer</p></li><li><p>Betriebsform</p></li><li><p>Tiername</p></li><li><p>Hauptadresse</p></li><li><p>Strasse</p></li><li><p>Hausnummer</p></li><li><p>PLZ</p></li><li><p>Stadt</p></li></ul><ul><li><p>Aktiv</p></li><li><p>Ost (Y)</p></li><li><p>Nord (X)</p></li><li><p>Höhe</p></li><li><p>Gebiet</p></li><li><p>Zone</p></li><li><p>BVD-Status</p></li><li><p>Moderhinkestatus</p></li></ul><p></p>", "fr": "<p>Concrètement, les données suivantes sont transmises:</p><p><br></p><p>Numéro REE</p><ul><li><p>Numéro BDTA</p></li><li><p>Numéro d’identification des entreprises</p></li><li><p>Forme d''exploitation</p></li><li><p>Nom</p></li><li><p>Adresse principale</p></li><li><p>Rue</p></li><li><p>Numéro de maison</p></li><li><p>NPA</p></li><li><p>Ville<br></p></li></ul><ul><li><p>Actif</p></li></ul><ul><li><p>Est (Y)</p></li><li><p>Nord (