n</p><ul><li><p>Numéro de marque auriculaire</p></li><li><p>Nom</p></li><li><p>Sexe</p></li><li><p>Race</p></li><li><p>Couleur</p></li><li><p>Date de naissance</p></li><li><p>Animal mort-né</p></li><li><p>Date de mort</p></li><li><p>Historique de l''animal</p></li><li><p>Type d''utilisation</p></li><li><p>Valable du</p></li><li><p>Première vêlage</p></li><li><p>Date du dernier vêlage</p></li><li><p>Castré</p></li><li><p>Naissance multiple</p></li></ul><p><br></p><p>Localisation</p><ul><li><p>Numéro REE de l''exploitation actuelle</p></li><li><p>Numéro BDTA de l''exploitation actuelle</p></li><li><p>Numéro REE Dernière exploitation à l''année</p></li><li><p>Numéro BDTA Dernière exploitation à l''année</p></li></ul><p><br></p><p>Parents</p><ul><li><p>Numéro de marque auriculaire&nbsp;(mère)</p></li><li><p>Race (mère)</p></li><li><p>Numéro de marque auriculaire (père)</p></li><li><p>Race (père)</p></li></ul><p><br></p><p>Diseases</p><ul><li><p>Statut BVD</p></li><li><p>Lumpy Skin disease statut de vaccination</p></li><li><p>Lumpy Skin disease date de vaccination</p></li></ul><p><br></p><p>Informations sur l’élevage Naissance</p><ul><li><p>IDE Organisation d''élevage initiale</p></li><li><p>ID Organisation d''élevage initiale</p></li><li><p>Déroulement du vêlage</p></li><li><p>Heure de la mort</p></li><li><p>Poids à la naissance</p></li><li><p>Certificat d''ascendance</p></li><li><p>Numéro de marque auriculaire de la mère génétique</p></li><li><p>Race de la mère génétique</p></li><li><p>Date IA, saillie ou transfert</p></li><li><p>Père validé par Swissgenetics</p></li></ul><p><br></p><p>Malformations</p><ul><li><p>Malformation</p></li></ul><p><br></p><p>Notifications</p><ul><li><p>dernière Date de notification</p></li><li><p>ID</p></li><li><p>Type de notification</p></li><li><p>Motif de sortie</p></li><li><p>Motif principal de sortie</p></li><li><p>Motif secondaire de sortie</p></li><li><p>Date de l’événement</p></li><li><p>Date de notification</p></li><li><p>Numéro REE</p></li><li><p>Numéro BDTA</p></li><li><p>Date de la suppression</p></li></ul><p><br></p><p>Exploitation d''origine</p><ul><li><p>Numéro REE Exploitation d''origine</p></li><li><p>Numéro BDTA Exploitation d''origine</p></li><li><p>IDE Organisation d''élevage actuelle</p></li><li><p>ID Organisation d''élevage actuelle</p></li><li><p>Date de notification</p></li><li><p>Date de la suppression</p></li></ul><p></p>", "it": "<p>Concretamente vengono trasmessi i dati seguenti:</p><p><br></p><p>Bovin</p><ul><li><p>Numero di marca auricolare</p></li><li><p>Nome</p></li><li><p>Sesso</p></li><li><p>Razza</p></li><li><p>Colore</p></li><li><p>Data di nascita</p></li><li><p>Animale nato morto</p></li><li><p>Data del decesso</p></li><li><p>Storia dell''animale</p></li><li><p>Tipo d''utilizzo</p></li><li><p>Valido da</p></li><li><p>Primo parto</p></li><li><p>Data dell''ultimo parto</p></li><li><p>Castrato</p></li><li><p>Parto gemellare</p></li></ul><p><br></p><p>Località</p><ul><li><p>Numero RIS dell''azienda attuale</p></li><li><p>Numero BDTA dell''azienda attuale</p></li><li><p>Numero RIS Ultima azienda annuale</p></li><li><p>Numero BDTA Ultima azienda annuale</p></li></ul><p><br></p><p>Parenti</p><ul><li><p>Numero di marca auricolare (madre)</p></li><li><p>Razza (madre)</p></li><li><p>Numero di marca auricolare (padre)</p></li><li><p>Razza (padre)</p></li></ul><p><br></p><p>Diseases<br>Stato BVD</p><ul><li><p>Lumpy Skin disease stato di vaccinazione</p></li><li><p>Lumpy Skin disease data della vaccinazione</p></li></ul><p><br></p><p>Informazioni Allevamento Nascita</p><ul><li><p>IDI Prima organizzazione d''allevamento</p></li><li><p>ID Prima organizzazione d''allevamento</p></li><li><p>Decorso del parto</p></li><li><p>Momento del decesso</p></li><li><p>Peso alla nascita</p></li><li><p>Certificato d''ascendenza</p></li><li><p>Numero di marca auricolare della madre genetica</p></li><li><p>Razza della madre genetica</p></li><li><p>Data IA, monta o trapianto</p></li><li><p>Padre convalidato da Swissgenetics</p></li></ul><p><br></p><p>Malformazioni</p><ul><li><p>Malformazione</p></li></ul><p><br></p><p>Notifiche</p><ul><li><p>Ultima data di notifica</p></li><li><p>ID</p></li><li><p>Tipo di notifica</p></li><li><p>Motivo dell''uscita</p></li><li><p>Motivo principale dell''uscita</p></li><li><p>Motivo secondario dell''uscita</p></li><li><p>Data dell’evento</p></li><li><p>Data della notifica</p></li><li><p>Numero RIS</p></li><li><p>Numero BDTA</p></li><li><p>Data di cancellazione</p></li></ul><p><br></p><p>Azienda d’origine</p><ul><li><p>Numero RIS Azienda d’origine</p></li><li><p>Numero BDTA Azienda d’origine</p></li><li><p>IDI Organizzazione d''allevamento attuale</p></li><li><p>ID Organizzazione d''allevamento attuale</p></li><li><p>Data della notifica</p></li><li><p>Data di cancellazione</p></li></ul><p></p>"}'::jsonb, '[]'::jsonb),
    ('88dcf0f9-8502-4596-b035-45c5d548d262', false, null, NOW(), null, NOW(), '{"de": "Ziegenbewegungsdaten Zucht", "fr": "Données sur les déplacements des chèvres - élevage", "it": "Dati sugli spostamenti delle capre dell’allevamento"}'::jsonb, '{"de": "Dieses Datenpaket enthält die Bewegungsdaten von ZO-zugewiesenen Ziegen innerhalb eines definierten Zeitraums (von–bis). Es umfasst aktualisierte Basisinformationen sowie Angaben zu Standort, Eltern, Zucht und Meldungen. Das Datenpaket ist den Ziegenzuchtorganisationen vorbehalten.", "fr": "Ce paquet de données contient les informations relatives aux déplacements des chèvres affectées à une OE au cours d’une période définie (de – à). Il contient des informations de base actualisées, ainsi que des informations sur la localisation, les parents, l’élevage et les notifications. Ce paquet de données est réservé aux organisations d’élevage de chèvres.", "it": "Questo pacchetto di dati contiene i dati relativi agli spostamenti delle capre assegnate all’organizzazione d’allevamento in un periodo di tempo definito (da – a). Comprende informazioni di base aggiornate, nonché informazioni su località, parenti, allevamento e notifiche. Il pacchetto di dati è riservato alle organizzazioni d’allevamento di capre."}'::jsonb, 'TVD_ZO_API', 'GET', 'api-zo/v1.0/shared-data/goat?dateTimeFrom={{dateTimeFrom}}&dateTimeTo={{dateTimeTo}}&dataPackage=ZOAPI_GoatDeltaV1&recipientUid={{recipientUid}}', null, 'UNBOUND_BUR_BASED_POST_VALIDATION', 'e93f1023-850d-4188-bf40-50e5eedaaa57', null, null, 'cadf12a3-af55-4919-8d30-6849ab6c13ba', 'ACTIVE', 'CHE105031830', false, null, '{"de": "<p>Konkret werden folgende Daten übermittelt:</p><p><br></p><p>Ziege</p><ul><li><p>Ohrmarkennummer</p></li><li><p>Tiername</p></li><li><p>Geschlecht</p></li><li><p>Rasse</p></li><li><p>Geburtsdatum</p></li><li><p>Todesdatum</p></li><li><p>Nutzungsart</p></li><li><p>Gültig von</p></li></ul><p><br></p><p>Standort</p><ul><li><p>BUR-Nummer aktuelle Tierhaltung</p></li><